const _ = require("lodash");

export default {
  props: ["orders", "graphReloadKey"],

  computed: {
    graphData() {
      let gd = [];

      _.each(this.orders, (order) => {
        let x = 0;
        // if (order["products"] && order["products"].length) {
        //   if (order["products"][0]["normalisedData"]) {
        //     let normalisedDatas = order["products"][0]["normalisedData"];
        //     let firstNormalisedData =
        //       normalisedDatas[Object.keys(normalisedDatas)[0]];
        //       if (firstNormalisedData) {
        //         x = firstNormalisedData["rawValue"];
        //       }
        //   }
        // }

        let cost = order["Cost"];
        let quantity = order["Quantity"] !== "None" ? order["Quantity"] : 0;

        gd.push({
          description: order['PO Li Description'],
          quantity: quantity,
          cost: cost,
          cost_per_unit: quantity ? cost / quantity : cost,
          x: x,
        });
      });

      return gd;
    },
  },

  data() {
    return {
      data: DATA,
      height: 500,
      pointTooltip: [
        "description*x*cost_per_unit",
        (description, x, cost_per_unit) => {
          return {
            name: description,
            value: x + "(x), " + cost_per_unit + "(cost per unit)",
          };
        },
      ],
      tooltipCrosshairs: { type: "cross" },
      tooltipItemTpl: `
        <li data-index={index} style="margin-bottom:4px;">
          <span style="background-color:{color};" class="g2-tooltip-marker"></span>
          {name}<br />{value}
        </li>
      `,
    };
  },
};
